python - <<'PY'
import json
with open('/app/benchmark/source_data.json') as f:
    src=json.load(f)

sp={r['country']: r for r in src['education_spending']['data']}
pisa={r['country']: r for r in src['pisa_scores']['data']}
enr={r['country']: r for r in src['tertiary_enrollment']['data']}
yur={r['country']: r for r in src['youth_unemployment']['data']}
rows=[]
for c in sp:
    rows.append({
        'country': c,
        'region': sp[c]['region'],
        'spend': sp[c]['edu_spending_pct_gdp'],
        'pisa': pisa[c]['pisa_avg'],
        'enroll': enr[c]['enrollment_rate'],
        'unemp': yur[c]['youth_unemp_rate'],
    })

# candidates: high spend>=6.0 OR low spend<=3.5 OR high pisa>=520 OR high unemp>=18 OR high enroll>=95
labels=[]
for r in rows:
    if r['spend']>=6.0 or r['spend']<=3.5 or r['pisa']>=520 or r['unemp']>=18 or r['enroll']>=95:
        labels.append(r)
print('label candidates',len(labels))
for r in sorted(labels, key=lambda x:(-x['spend'], -x['unemp'])):
    print(r)
PY

